public final class ResultRow
{
  private final Object[] row;

  private ResultRow(final Object[] row)
  {
    this.row = row;
  }

  /**
   * Create a row from an array of objects.
   */
  @JsonCreator
  public static ResultRow of(final Object... row)
  {
    return new ResultRow(row);
  }

  /**
