  public static final NodeRole MIDDLE_MANAGER = new NodeRole("MIDDLE_MANAGER", MIDDLE_MANAGER_JSON_NAME);
  public static final NodeRole INDEXER = new NodeRole("INDEXER", INDEXER_JSON_NAME);

