    q = mfqp.parse("one AND two AND foo:test");
    assertEquals("+((b:one)^5.0 (t:one)^10.0) +((b:two)^5.0 (t:two)^10.0) +foo:test", q.toString());

    q = mfqp.parse("one^3 AND two^4");
