	} else {
		in.String = m.filterCookieString(in.String)
	}

	return in
}

// filterCookieString applies the configured actions to a single
// Cookie header value and returns the transformed value.
func (m CookieFilter) filterCookieString(value string) string {
	originRequest := http.Request{Header: http.Header{"Cookie": []string{value}}}
	cookies := originRequest.Cookies()
	transformedRequest := http.Request{Header: make(http.Header)}

OUTER:
	for _, c := range cookies {
		for _, a := range m.Actions {
			if c.Name != a.Name {
				continue
			}

			switch a.Type {
			case replaceAction:
				c.Value = a.Value
				transformedRequest.AddCookie(c)
				continue OUTER

			case hashAction:
				c.Value = hash(c.Value)
				transformedRequest.AddCookie(c)
				continue OUTER

			case deleteAction:
				continue OUTER
			}
		}

		transformedRequest.AddCookie(c)
	}

	return transformedRequest.Header.Get("Cookie")
}

