+
+  std::filesystem::path p = "foo/bar";
+  // Prints "foo/bar"
+  fmt::print("{}", p);
+  // Prints the native format, e.g. "foo\\bar" on Windows
+  fmt::print("{:n}", p);
+  // Prints the generic format, e.g. "foo/bar" on Windows
+  fmt::print("{:g}", p);
