+		// resource or in any of its ancestor modules, so we must search the
+		// whole chain of ancestor modules for a matching removed block. This
+		// is also necessary when the resource's own module has been removed
+		// from configuration entirely, in which case there is no config for
+		// that module but an ancestor may still declare a "removed" block.
+		for _, ancestor := range addr.Module.Ancestors() {
+			ancestorCfg := t.Config.Descendent(ancestor)
+			if ancestorCfg == nil {
 				continue
