+// findRemovedBlock searches the configuration tree for a "removed" block
+// targeting the given resource address, returning nil if there is none.
+//
+// A "removed" block may be declared in the same module as the resource it
+// targets or in any ancestor module, with its "from" address interpreted
+// relative to the module where it is declared. When more than one block
+// targets the same resource, the one declared in the outermost module wins,
+// matching the behavior of the refactoring package.
+func (t *AttachResourceConfigTransformer) findRemovedBlock(addr addrs.ConfigResource) *configs.Removed {
+	var found *configs.Removed
+	t.Config.DeepEach(func(cfg *configs.Config) {
+		if found != nil {
+			return
+		}
+		for _, r := range cfg.Module.Removed {
+			crAddr, ok := r.From.RelSubject.(addrs.ConfigResource)
+			if !ok {
+				// Not for a resource at all, so can't possibly match
+				continue
+			}
+
+			// Stitch together the module path of the module where the block
+			// is declared and the relative address to form the absolute
+			// address of the target resource.
+			absAddr := addrs.ConfigResource{
+				Module:   append(append(addrs.Module{}, cfg.Path...), crAddr.Module...),
+				Resource: crAddr.Resource,
+			}
+			if absAddr.Equal(addr) {
+				found = r
+				return
+			}
+		}
+	})
+	return found
+}

