index 7f810d751b..2f7183bf21 100644
--- a/src/Illuminate/Validation/Concerns/FormatsMessages.php
+++ b/src/Illuminate/Validation/Concerns/FormatsMessages.php
@@ -117,6 +117,10 @@ protected function getFromLocalArray($attribute, $lowerRule, $source = null)
                             return $message[$lowerRule];
                         }

+                        if (is_array($message) && ! in_array(Str::studly($lowerRule), $this->sizeRules)) {
