         $thousandsSeparator = StringHelper::getThousandsSeparator();
         $decimalSeparator = StringHelper::getDecimalSeparator();
         if ($thousandsSeparator !== ',' || $decimalSeparator !== '.') {
-            $value = str_replace(['.', ',', "\u{fffd}"], ["\u{fffd}", '.', ','], $value);
