        return NULL;
    } else {
        raxFreeWithCallback(Users, ACLFreeUserVoid);
        Users = old_users;
        errors =
            sdscat(errors, "WARNING: ACL errors detected, no change to the previously active ACL rules was performed");
        return errors;
    }
}

